SELECT * FROM file_record
WHERE file_md5 = #{md5}
LIMIT 1

SELECT COUNT(*) FROM file_record
WHERE uploader_id = #{uploaderId}
AND status = 1

SELECT * FROM file_record


        AND file_type = #{params.fileType}


        AND uploader_id = #{params.uploaderId}


        AND status = #{params.status}


        AND (original_file_name LIKE CONCAT('%', #{params.keyword}, '%')
             OR description LIKE CONCAT('%', #{params.keyword}, '%'))


ORDER BY upload_time DESC
